1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { Bike } from 'lucide-react';
14	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
15	import {
16	  expectedWeekFraction,
17	  parseBrDateTime,
18	  parseIsoDateLocal,
19	} from '../model/tvMath';
20	import { TvDeltaChip, TvLiveIndicator, TvMetaBar, TvRankChip, TvStateChip } from './TvChips';
21	import {
22	  TvColumnBipLine,
23	  TvColumnMetaBar,
24	  TvColumnStockLine,
25	  TvUnitColumn,
26	} from './TvColumnParts';
27	import {
28	  formatExactBRL,
29	  formatTicketBRL,
30	  formatWeekdayDayMonth,
31	  metaBarColorFromRatio,
32	  type TvBarColor,
33	} from './tvFormat';
34	import { useCountUp } from './useCountUp';
35	
36	interface TvStoreColumnProps {
37	  store: TvStoreData;
38	  liveLevel: TvFreshnessLevel;
39	  period: TvPeriod;
40	  now: Date;
41	  rank?: number | null;
42	}
43	
44	/** Coluna de loja — canal Degust live ou Linx defasado. */
45	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
46	  const { vendas, channel } = store;
47	  const isLive = channel === 'degust-live';
48	  const valorAnim = useCountUp(vendas?.valor ?? 0);
49	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
50	
51	  // Flash dourado ao atualizar o valor de venda
52	  const prevValueRef = useRef(vendas?.valor);
53	  const [flashing, setFlashing] = useState(false);
54	  const flashKeyRef = useRef(0);
55	  useEffect(() => {
56	    if (
57	      vendas?.valor != null &&
58	      prevValueRef.current != null &&
59	      vendas.valor !== prevValueRef.current
60	    ) {
61	      flashKeyRef.current += 1;
62	      setFlashing(true);
63	      const t = window.setTimeout(() => setFlashing(false), 450);
64	      prevValueRef.current = vendas.valor;
65	      return () => window.clearTimeout(t);
66	    }
67	    prevValueRef.current = vendas?.valor;
68	  }, [vendas?.valor]);
69	
70	  // Linha de status: fonte + horário de atualização
71	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
72	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
73	
74	  const showRank = rank != null && rank >= 1 && rank <= 3;
75	
76	  return (
77	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
78	
79	      {/* Header: nome + chips de status */}
80	      <div className="flex items-start justify-between gap-2">
81	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
82	          {store.nome.replace(/^Momma\s+/i, '')}
83	        </h2>
84	        <div className="flex shrink-0 items-center gap-1">
85	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
86	          <TvStateChip rag={store.rag} />
87	        </div>
88	      </div>
89	
90	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
91	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
92	        <span
93	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
94	          className={`font-momma text-[clamp(1.375rem,1.9vw,2.5rem)] font-bold leading-none tabular-nums ${
95	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
96	          }${flashing ? ' tv-value-flash' : ''}`}
97	          data-testid="tv-store-sales"
98	        >
99	          {/* CountUp anima o número bruto; o EXATO é formatado a cada frame */}
100	          {vendas ? formatExactBRL(valorAnim) : '—'}
101	        </span>
102	        {store.deltaOntem != null && (
103	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
104	        )}
105	        {store.deltaSemana != null && period === 'week' && (
106	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
107	        )}
108	      </div>
109	
110	      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
111	          o número principal acima segue sendo o TOTAL oficial */}
112	      {store.deliverySplit && (
113	        <p
114	          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
115	          data-testid="tv-delivery-split"
116	        >
117	          <span className="whitespace-nowrap">
118	            Loja{' '}
119	            <span className="font-medium text-[#5F6F63]">
120	              {formatExactBRL(store.deliverySplit.balcao)}
121	            </span>
122	          </span>
123	          <span aria-hidden>·</span>
124	          <span className="inline-flex items-center gap-1 whitespace-nowrap">
125	            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
126	            Delivery{' '}
127	            <span className="font-medium text-[#5F6F63]">
128	              {formatExactBRL(store.deliverySplit.delivery)}
129	            </span>
130	          </span>
131	        </p>
132	      )}
133	
134	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
135	      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
136	        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
137	        {isLive
138	          ? updateTime
139	            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
140	            : 'hoje'
141	          : laggedLabel ?? 'sem dados'}
142	      </p>
143	
144	      {/* Barra de meta do DIA */}
145	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
146	
147	      {/* Meta da SEMANA corrente (seg–dom) — linha secundária, não compete
148	          com o número grande de vendas do dia. Ausente quando a loja não
149	          tem meta mensal cadastrada (weeklyGoal null/undefined). */}
150	      {store.weeklyGoal && (
151	        <TvStoreWeeklyGoalLine weeklyGoal={store.weeklyGoal} now={now} />
152	      )}
153	
154	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
155	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
156	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
157	          {vendas?.cupons != null && (
158	            <span className="whitespace-nowrap font-medium">
159	              {vendas.cupons} vendas
160	            </span>
161	          )}
162	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
163	            <span className="whitespace-nowrap">
164	              {vendas.cupons != null && '· '}
165	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
166	              <span>/venda</span>
167	            </span>
168	          )}
169	        </div>
170	      )}
171	
172	      {/* Bip + Status de estoque — 1 linha para cada */}
173	      <div className="mt-auto pt-3 space-y-1">
174	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
175	        <TvColumnStockLine estoque={store.estoque} />
176	      </div>
177	    </TvUnitColumn>
178	  );
179	}
180	
181	/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
182	const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
183	  sage: 'text-[#57715B]',
184	  amber: 'text-amber-600',
185	  red: 'text-red-600',
186	};
187	
188	/**
189	 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
190	 * (cor pace-adjusted pela mesma régua da diária/mensal; emerald quando
191	 * ≥ 100%) + valores exatos "R$ X / R$ Y" + mini barra de progresso
192	 * ({@link TvMetaBar} mini com tick dourado no esperado-agora da semana).
193	 *
194	 * COR pace-adjusted: ratio = %real / %esperado-agora, com esperado =
195	 * dias decorridos ÷ dias do segmento seg-dom corrente do mês
196	 * ({@link expectedWeekFraction} — derivado localmente porque o
197	 * `weeklyGoal` do model não expõe o segmento). Começo de semana no ritmo
198	 * NÃO fica vermelho. O % NUMÉRICO exibido segue sendo o real.
199	 */
200	function TvStoreWeeklyGoalLine({
201	  weeklyGoal,
202	  now,
203	}: {
204	  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
205	  now: Date;
206	}) {
207	  const { target, achieved, pct } = weeklyGoal;
208	  const beaten = pct != null && pct >= 100;
209	  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
210	  const barColor: TvBarColor = beaten
211	    ? 'sage'
212	    : metaBarColorFromRatio(
213	        pct != null && expectedWeekPct > 0 ? pct / expectedWeekPct : null,
214	        now,
215	      );
216	  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];
217	
218	  return (
219	    <div className="mt-2" data-testid="tv-weekly-goal">
220	      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
221	        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
222	          SEMANA
223	        </span>
224	        {/* Sem truncate: valor exato nunca pode ser cortado — quebra linha */}
225	        <span className="min-w-0 text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
226	          <span
227	            className={`text-xs font-bold tabular-nums ${pctCls}`}
228	            data-testid="tv-weekly-goal-pct"
229	          >
230	            {pct != null ? `${Math.round(pct)}%` : '—'}
231	          </span>{' '}
232	          {formatExactBRL(achieved)} / {formatExactBRL(target)}
233	        </span>
234	      </div>
235	      <div className="mt-1">
236	        <TvMetaBar
237	          fillPct={pct}
238	          expectedPct={pct != null ? expectedWeekPct : null}
239	          color={barColor}
240	          size="mini"
241	        />
242	      </div>
243	    </div>
244	  );
245	}
