{store.staleLive ? (
  <p className="mt-1 flex items-center gap-1.5 text-xs text-amber-600 dark:text-amber-500">
    <AlertTriangle className="h-3 w-3 shrink-0 text-amber-600 dark:text-amber-500" aria-hidden />
    {`sem sincronia desde ${new Date(store.staleLive.since).getHours().toString().padStart(2, '0')}:${new Date(store.staleLive.since).getMinutes().toString().padStart(2, '0')}`}
  </p>
) : (
  <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
    <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
    {isLive
      ? updateTime
        ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
        : 'hoje'
      : laggedLabel ?? 'sem dados'}
  </p>
)}
